import { isUnifiedTranscript } from "./transcript-parsers/unified-transcript-parser"

export interface StoredTranscriptSession {
  content: string
  ref?: string
  path?: string
  filename?: string
}

interface StoredTranscriptPayload {
  schemaVersion: 1
  sessions: Record<string, StoredTranscriptSession>
}

function filenameFromPath(path?: string): string | undefined {
  if (!path) return undefined
  const parts = path.split("/")
  return parts[parts.length - 1] || undefined
}

function normalizeStoredTranscriptSessions(
  value: unknown,
): Record<string, StoredTranscriptSession> | null {
  if (typeof value !== "object" || value === null || Array.isArray(value)) {
    return null
  }

  const out: Record<string, StoredTranscriptSession> = {}
  for (const [key, entry] of Object.entries(value)) {
    if (typeof entry === "string") {
      out[key] = { content: entry }
      continue
    }

    if (typeof entry !== "object" || entry === null || Array.isArray(entry)) {
      continue
    }

    const session = entry as Record<string, unknown>
    if (typeof session.content !== "string") {
      continue
    }

    const path = typeof session.path === "string" ? session.path : undefined
    const filename =
      typeof session.filename === "string" ? session.filename : filenameFromPath(path)

    out[key] = {
      content: session.content,
      ref: typeof session.ref === "string" ? session.ref : undefined,
      path,
      filename,
    }
  }

  return out
}

export function serializeStoredTranscriptSessions(
  sessions: Record<string, StoredTranscriptSession>,
): string {
  const payload: StoredTranscriptPayload = {
    schemaVersion: 1,
    sessions,
  }

  return JSON.stringify(payload)
}

export function parseStoredTranscriptSessions(
  raw: string,
): Record<string, StoredTranscriptSession> | null {
  try {
    const parsed = JSON.parse(raw) as unknown
    if (typeof parsed !== "object" || parsed === null || Array.isArray(parsed)) {
      return null
    }

    const maybePayload = parsed as Record<string, unknown>
    const sessionsValue =
      maybePayload.schemaVersion === 1 && "sessions" in maybePayload
        ? maybePayload.sessions
        : parsed

    return normalizeStoredTranscriptSessions(sessionsValue)
  } catch {
    return null
  }
}

export function shouldUseUnifiedParserForStoredSession(
  session: StoredTranscriptSession | undefined,
  _storageVersion?: number | null,
): boolean {
  if (session) {
    const filename = session.filename ?? filenameFromPath(session.path)
    if (
      filename === "transcript.jsonl" ||
      session.path?.endsWith("/transcript.jsonl") ||
      isUnifiedTranscript(session.content)
    ) {
      return true
    }
  }

  return false
}

