import { CHECKPOINT_BRANCH } from "./constants"

export type CheckpointStorageVersion = number

export const CHECKPOINT_V1_STORAGE_VERSION = 1

export function getCheckpointSourceRefForPush(ref?: string | null): string | null {
  return ref === `refs/heads/${CHECKPOINT_BRANCH}` ? CHECKPOINT_BRANCH : null
}

export function getCheckpointStorageVersionForSourceRef(
  _sourceRef: string,
): CheckpointStorageVersion {
  return CHECKPOINT_V1_STORAGE_VERSION
}

export interface CheckpointTranscriptLocation {
  ref: string
  transcriptFilename: string
  usesUnifiedTranscriptParser: boolean
}

const CHECKPOINT_V1_TRANSCRIPT_LOCATION: CheckpointTranscriptLocation = {
  ref: CHECKPOINT_BRANCH,
  transcriptFilename: "full.jsonl",
  usesUnifiedTranscriptParser: false,
}

export function getCheckpointTranscriptLocation(
  _storageVersion?: CheckpointStorageVersion | null,
): CheckpointTranscriptLocation {
  return CHECKPOINT_V1_TRANSCRIPT_LOCATION
}

export interface CheckpointSyncLocation {
  storageVersion: CheckpointStorageVersion
  sourceRef: string
}

const CHECKPOINT_V1_SYNC_LOCATION: CheckpointSyncLocation = {
  storageVersion: CHECKPOINT_V1_STORAGE_VERSION,
  sourceRef: CHECKPOINT_V1_TRANSCRIPT_LOCATION.ref,
}

/** Default sync location for newly-discovered checkpoints. Always v1. */
export function resolveCheckpointSyncLocation(): CheckpointSyncLocation {
  return CHECKPOINT_V1_SYNC_LOCATION
}

   * operators can tell "rate-limit vs OOM vs other" without grepping
   * Cloudflare logs.
   */
  transientErrors: TranscriptFetchError[]
}

/**
 * Fetch raw transcripts from GitHub, slice, and strip them for storage.
 * Uses per-session agent metadata to select the correct parser for each session.
 * Returns a per-session map with stripped content and source provenance plus a flag
 * indicating whether any non-404 error tainted the result.
 *
 * Returns `null` only when the overall operation threw catastrophically (e.g. root
 * metadata unreadable). In that case callers have no usable state at all.
 */
export async function fetchAndStripTranscripts(
  repoProvider: RepoReadProvider,
  repoFullName: string,
  checkpointId: string,
  sessionCount: number,
  defaultAgent: string,
  sessionMetadata: SessionInfo[] | null,
  storageVersion: CheckpointStorageVersion = CHECKPOINT_V1_STORAGE_VERSION,
  token: string,
): Promise<TranscriptFetchResult | null> {
  try {
    const folder = checkpointFolderPath(checkpointId)
    const sessions: Record<string, StoredTranscriptSession> = {}
    const transcriptLocation = getCheckpointTranscriptLocation(storageVersion)
    const transientErrors: TranscriptFetchError[] = []
    const metadataContent = await repoProvider
      .getFileAtCommit(repoFullName, `${folder}/metadata.json`, transcriptLocation.ref, token)
      .catch((err: unknown) => {
        transientErrors.push({
          path: `${folder}/metadata.json`,
          sessionIndex: null,
          error: errorString(err),
        })
        return null
      })

    let transcriptPaths: string[] | null = null
    if (metadataContent) {
      try {
        const checkpointMeta = JSON.parse(metadataContent) as CheckpointMetadata
        if (checkpointMeta.sessions && checkpointMeta.sessions.length > 0) {
          transcriptPaths = checkpointMeta.sessions
            .slice(0, MAX_SESSIONS_PER_CHECKPOINT)
            .map((session, index) =>
              typeof session.transcript === "string" && session.transcript
                ? stripLeadingSlash(session.transcript)
                : `${folder}/${index}/${transcriptLocation.transcriptFilename}`,
            )
        }
      } catch {
        console.warn(
          `[transcript-storage] Invalid JSON in checkpoint metadata: ${folder}/metadata.json`,
        )
      }
    }

    if (!transcriptPaths) {
      const count = Math.min(Math.max(sessionCount, 1), MAX_SESSIONS_PER_CHECKPOINT)
      transcriptPaths = Array.from(
        { length: count },
        (_, index) => `${folder}/${index}/${transcriptLocation.transcriptFilename}`,
      )
    }

    // Bulk-fetch the per-session transcripts in a single provider call. For
    // go-git-api this collapses N Connect round-trips into one `GetFiles`
    // RPC; for the GitHub provider the underlying fan-out uses
    // `Promise.allSettled` so a single transient miss only nulls that path
    // instead of poisoning the batch. The per-path callback is what tells
    // us "this null came from a 5xx, not a 404" — we record it in
    // `transientErrors` so dead-session persistence is suppressed.
    const pathIndex = new Map(transcriptPaths.map((p, i) => [p, i]))
    let resultsByPath: Map<string, string | null>
    try {
      resultsByPath = await repoProvider.getFilesAtCommit(
        repoFullName,
        transcriptPaths,
        transcriptLocation.ref,
        token,
        {
          onTransientPath: (path, err) => {
            transientErrors.push({
              path,
              sessionIndex: pathIndex.get(path) ?? null,
              error: errorString(err),
            })
          },
        },
      )
    } catch (err) {
      transientErrors.push({
        path: WHOLESALE_FAILURE_PATH,
        sessionIndex: null,
        error: errorString(err),
      })
      resultsByPath = new Map()
    }

    for (let i = 0; i < transcriptPaths.length; i++) {
      const content = resultsByPath.get(transcriptPaths[i]) ?? null
      if (content) {
        const sessionAgent = sessionMetadata?.[i]?.agent ?? defaultAgent
        const parser = getParserForAgent(sessionAgent, {
          enableUnifiedTranscriptParser: transcriptLocation.usesUnifiedTranscriptParser,
        })
        // Backfill the model from the transcript when committed metadata left
        // it blank (e.g. Pi records it in-band via model_change, not in
        // metadata.json). Read the full unsliced content — the model_change
        // event lives at the session start, which is before this checkpoint's
        // slice window for any checkpoint past the first. Mutates the shared
        // SessionInfo so the hydrator persists it on the checkpoint row.
        backfillSessionModel(sessionMetadata?.[i], parser, content)
        const slicedContent = sliceTranscriptForStorage(
          content,
          parser,
          getSessionCheckpointTranscriptStart(sessionMetadata, i),
        )
        const path = transcriptPaths[i]
        sessions[String(i)] = {
          content: stripTranscript(slicedContent, parser),
          ref: transcriptLocation.ref,
          path,
          filename: path.split("/").pop() ?? transcriptLocation.transcriptFilename,
        }
      }
    }

    return { sessions, transientErrors }
  } catch (err) {
    console.error(
      `[transcript-storage] fetchAndStripTranscripts error: checkpoint=${checkpointId}`,
      err instanceof Error ? err.message : err,
    )
    return null
  }

