import type { TranscriptMessage } from "../../types"
import { getParserForAgent, type ParserOptions } from "./registry"
import type { TranscriptParseResult } from "./types"

/**
 * Filter messages to only include those after a given identifier.
 * Used for UUID-based filtering: messages after the identifier are
 * the "new" messages from the current checkpoint.
 */
export function filterRelevantMessages(
  messages: TranscriptMessage[],
  transcriptIdentifierAtStart: string | null,
): TranscriptMessage[] {
  if (!transcriptIdentifierAtStart) return messages
  const startIndex = messages.findIndex((msg) => msg.id === transcriptIdentifierAtStart)
  if (startIndex === -1) return messages
  return messages.slice(startIndex + 1)
}

/**
 * Three-way transcript resolution:
 *   1. UUID-based filtering  (transcriptIdentifierAtStart present)
 *   2. Offset-based filtering (checkpointTranscriptStart > 0)
 *   3. No filtering           (neither present -- return everything)
 *
 * Returns both the filtered messages and the parse result (for isFallback / warning).
 */
export function resolveTranscript(
  transcriptContent: string,
  agent: string,
  transcriptIdentifierAtStart: string | null,
  checkpointTranscriptStart: number | null,
  parserOptions?: ParserOptions,
): { messages: TranscriptMessage[]; parseResult: TranscriptParseResult } {
  const parser = getParserForAgent(agent, parserOptions)

  if (transcriptIdentifierAtStart) {
    const parseResult = parser.parse(transcriptContent)
    const messages = filterRelevantMessages(parseResult.messages, transcriptIdentifierAtStart)
    return { messages, parseResult }
  }

  if (checkpointTranscriptStart && checkpointTranscriptStart > 0 && parser.parseFrom) {
    const parseResult = parser.parseFrom(transcriptContent, checkpointTranscriptStart)
    // If the offset cut everything away, fall back to the unfiltered parse so
    // the commit/checkpoint page renders the full log rather than nothing.
    if (parseResult.messages.length > 0) {
      return { messages: parseResult.messages, parseResult }
    }
  }

  const parseResult = parser.parse(transcriptContent)
  return { messages: parseResult.messages, parseResult }
}

