			t.Errorf("line %d: agent = %q, want %q", i, line.Agent, "claude-code")
		}
	}
	if lines[0].Type != "user" || lines[1].Type != "assistant" {
		t.Errorf("unexpected line types: %q, %q", lines[0].Type, lines[1].Type)
